/* tests/arm64_address_contract.c
 *
 * Regression contract for AArch64 (A64) memory addressing details.
 *
 * The expected values in this file are derived independently from the
 * A64 encoding rules (bit-field layouts of the load/store instructions)
 * or recorded by hand for a few benchmark encodings.  Nothing here is
 * generated by running Capstone.
 *
 * For every instruction we check the detail fields later analysis relies
 * on: mem.base / mem.index / mem.disp, shift type and value, ext,
 * writeback, post_index and cs_regs_access().  Pre-index and post-index
 * are treated as different shapes on purpose: a pre-index offset lives in
 * the MEM operand's disp, a post-index update is a separate IMM operand
 * with mem.disp == 0.
 *
 * Each check is tagged.  Group tags (unsigned_offset, signed_pre,
 * post_index, register_offset, pair, sp_base, api_reuse) gate the PASS
 * lines.  Three extra tags (signed_offset, base_writeback, and the
 * positive form of post_index) isolate single decoding behaviours so the
 * mutation runner can tell exactly which behaviour a mutant broke.
 *
 * Exit status is 0 only when every check passed.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#include <capstone/capstone.h>

static csh handle;

/* ------------------------------------------------------------------ */
/* failure bookkeeping                                                 */
/* ------------------------------------------------------------------ */

#define MAX_TAGS 16

static struct {
	const char *name;
	unsigned count;
} tag_fail[MAX_TAGS];
static unsigned tag_num;
static unsigned total_failures;

static void tag_hit(const char *tag)
{
	unsigned i;

	for (i = 0; i < tag_num; i++) {
		if (strcmp(tag_fail[i].name, tag) == 0) {
			tag_fail[i].count++;
			return;
		}
	}
	if (tag_num < MAX_TAGS) {
		tag_fail[tag_num].name = tag;
		tag_fail[tag_num].count = 1;
		tag_num++;
	}
	total_failures++;
}

static unsigned tag_failed(const char *tag)
{
	unsigned i;

	for (i = 0; i < tag_num; i++)
		if (strcmp(tag_fail[i].name, tag) == 0)
			return tag_fail[i].count;
	return 0;
}

static void check_field(const char *tag, int ok, uint32_t word, unsigned idx,
			const char *field, long long expect, long long got)
{
	if (ok)
		return;
	tag_hit(tag);
	printf("FAIL %s word=0x%08x idx=%u field=%s expected=%lld got=%lld\n",
	       tag, word, idx, field, expect, got);
}

/* ------------------------------------------------------------------ */
/* A64 encoding helpers (the independent reference)                    */
/* ------------------------------------------------------------------ */

/* sign-extend a value held in the low `bits` of v */
static int32_t sext(uint32_t v, int bits)
{
	uint32_t sign = 1u << (bits - 1);

	return (int32_t)((v ^ sign) - sign);
}

/* LDR/STR (immediate, unsigned offset): size 111 0 01 opc imm12 Rn Rt */
static uint32_t enc_unsigned(int size, int load, unsigned imm12,
			     unsigned rn, unsigned rt)
{
	return ((uint32_t)size << 30) | 0x39000000u | ((uint32_t)load << 22) |
	       ((imm12 & 0xfffu) << 10) | ((rn & 31u) << 5) | (rt & 31u);
}

/* LDR/STR (immediate, 9-bit signed): mode 0 = unscaled, 1 = post, 3 = pre */
static uint32_t enc_imm9(int size, int load, int mode, int imm,
			 unsigned rn, unsigned rt)
{
	return ((uint32_t)size << 30) | 0x38000000u | ((uint32_t)load << 22) |
	       (((uint32_t)imm & 0x1ffu) << 12) | ((uint32_t)mode << 10) |
	       ((rn & 31u) << 5) | (rt & 31u);
}

/* LDR/STR (register offset): option selects the extend, S the scale */
static uint32_t enc_regoff(int size, int load, unsigned rm, unsigned option,
			   unsigned s, unsigned rn, unsigned rt)
{
	return ((uint32_t)size << 30) | 0x38200800u | ((uint32_t)load << 22) |
	       ((rm & 31u) << 16) | ((option & 7u) << 13) |
	       ((s & 1u) << 12) | ((rn & 31u) << 5) | (rt & 31u);
}

/* LDP/STP: mode 0 = signed offset, 1 = post-index, 2 = pre-index */
static uint32_t enc_pair(int is64, int load, int mode, int imm7,
			 unsigned rt2, unsigned rn, unsigned rt)
{
	uint32_t base = is64 ? 0xa9000000u : 0x29000000u;

	if (mode == 1)
		base -= 0x00800000u;
	else if (mode == 2)
		base += 0x00800000u;
	if (load)
		base += 0x00400000u;
	return base | (((uint32_t)imm7 & 0x7fu) << 15) |
	       ((rt2 & 31u) << 10) | ((rn & 31u) << 5) | (rt & 31u);
}

static arm64_reg xreg(unsigned n) { return (arm64_reg)(ARM64_REG_X0 + n); }
static arm64_reg wreg(unsigned n) { return (arm64_reg)(ARM64_REG_W0 + n); }
static arm64_reg reg_for(int size, unsigned n)
{
	return size == 3 ? xreg(n) : wreg(n);
}

/* ------------------------------------------------------------------ */
/* test case description                                               */
/* ------------------------------------------------------------------ */

typedef struct {
	uint8_t type;		/* ARM64_OP_* */
	uint16_t reg;		/* REG: register id */
	int64_t imm;		/* IMM: immediate value */
	uint16_t base;		/* MEM: base register */
	uint16_t index;		/* MEM: index register */
	int32_t disp;		/* MEM: displacement */
	uint8_t sft;		/* shift type */
	uint8_t sval;		/* shift value */
	uint8_t ext;		/* extender */
	uint8_t acc;		/* REG: expected access, 0 = do not check */
} op_exp;

typedef struct {
	uint32_t word;
	uint8_t nops;
	uint8_t writeback;
	uint8_t post_index;
	op_exp ops[4];
	uint16_t must_read[5];
	uint8_t nread;
	uint16_t must_write[5];
	uint8_t nwrite;
	uint16_t not_read[3];
	uint8_t nnotread;
	uint16_t not_write[3];
	uint8_t nnotwrite;
	uint16_t wb_base;	/* base register expected in the write set */
} tc_t;

static int reg_in(const cs_regs regs, unsigned n, uint16_t r)
{
	unsigned i;

	for (i = 0; i < n; i++)
		if (regs[i] == r)
			return 1;
	return 0;
}

static void check_case(const char *group, const tc_t *tc, const cs_insn *insn,
		       unsigned idx)
{
	uint32_t w = tc->word;
	const cs_arm64 *a = &insn->detail->arm64;
	unsigned j, nop;
	cs_regs rd, wr;
	uint8_t nr = 0, nw = 0;

	check_field(group, a->op_count == tc->nops, w, idx, "op_count",
		    tc->nops, a->op_count);
	check_field(group, (int)a->writeback == tc->writeback, w, idx,
		    "writeback", tc->writeback, a->writeback);
	/* a true post_index flag is its own named behaviour */
	check_field(tc->post_index ? "post_index" : group,
		    (int)a->post_index == tc->post_index, w, idx, "post_index",
		    tc->post_index, a->post_index);

	nop = a->op_count < tc->nops ? a->op_count : tc->nops;
	for (j = 0; j < nop; j++) {
		const op_exp *e = &tc->ops[j];
		const cs_arm64_op *o = &a->operands[j];
		char field[32];

		snprintf(field, sizeof(field), "op%u.type", j);
		check_field(group, o->type == e->type, w, idx, field,
			    e->type, o->type);
		if (o->type != e->type)
			continue;
		switch (e->type) {
		case ARM64_OP_REG:
			snprintf(field, sizeof(field), "op%u.reg", j);
			check_field(group, o->reg == e->reg, w, idx, field,
				    e->reg, o->reg);
			if (e->acc) {
				snprintf(field, sizeof(field), "op%u.access", j);
				check_field(group, o->access == e->acc, w, idx,
					    field, e->acc, o->access);
			}
			break;
		case ARM64_OP_IMM:
			snprintf(field, sizeof(field), "op%u.imm", j);
			check_field(group, o->imm == e->imm, w, idx, field,
				    (long long)e->imm, (long long)o->imm);
			break;
		case ARM64_OP_MEM:
			snprintf(field, sizeof(field), "op%u.mem.base", j);
			check_field(group, o->mem.base == e->base, w, idx,
				    field, e->base, o->mem.base);
			snprintf(field, sizeof(field), "op%u.mem.index", j);
			check_field(group, o->mem.index == e->index, w, idx,
				    field, e->index, o->mem.index);
			snprintf(field, sizeof(field), "op%u.mem.disp", j);
			/* negative displacements are a named behaviour */
			check_field(e->disp < 0 ? "signed_offset" : group,
				    o->mem.disp == e->disp, w, idx, field,
				    e->disp, o->mem.disp);
			snprintf(field, sizeof(field), "op%u.shift.type", j);
			check_field(group, o->shift.type == e->sft, w, idx,
				    field, e->sft, o->shift.type);
			snprintf(field, sizeof(field), "op%u.shift.value", j);
			check_field(group, o->shift.value == e->sval, w, idx,
				    field, e->sval, o->shift.value);
			snprintf(field, sizeof(field), "op%u.ext", j);
			check_field(group, o->ext == e->ext, w, idx, field,
				    e->ext, o->ext);
			break;
		default:
			break;
		}
	}

	if (cs_regs_access(handle, insn, rd, &nr, wr, &nw) != CS_ERR_OK) {
		tag_hit(group);
		printf("FAIL %s word=0x%08x idx=%u field=regs_access error\n",
		       group, w, idx);
		return;
	}
	for (j = 0; j < tc->nread; j++)
		check_field(group, reg_in(rd, nr, tc->must_read[j]), w, idx,
			    "regs_read", tc->must_read[j], 0);
	for (j = 0; j < tc->nwrite; j++)
		check_field(group, reg_in(wr, nw, tc->must_write[j]), w, idx,
			    "regs_write", tc->must_write[j], 0);
	if (tc->wb_base != ARM64_REG_INVALID)
		/* writeback must put the base register in the write set */
		check_field("base_writeback", reg_in(wr, nw, tc->wb_base), w,
			    idx, "regs_write_base", tc->wb_base, 0);
	for (j = 0; j < tc->nnotread; j++)
		check_field(group, !reg_in(rd, nr, tc->not_read[j]), w, idx,
			    "regs_read_absent", tc->not_read[j], 0);
	for (j = 0; j < tc->nnotwrite; j++)
		check_field(group, !reg_in(wr, nw, tc->not_write[j]), w, idx,
			    "regs_write_absent", tc->not_write[j], 0);
}

/* words of every group, registered for the api_reuse weave */
static const uint32_t *group_words[8];
static size_t group_words_len[8];
static unsigned group_words_num;

static void run_cases(const char *group, const tc_t *cases, size_t n)
{
	uint8_t buf[4 * 128];
	uint32_t *words;
	cs_insn *insns = NULL;
	size_t cnt, i, m;

	if (n > 128) {
		tag_hit(group);
		printf("FAIL %s internal case overflow\n", group);
		return;
	}
	words = (uint32_t *)malloc(n * sizeof(uint32_t));
	if (!words) {
		tag_hit(group);
		printf("FAIL %s out of memory\n", group);
		return;
	}
	for (i = 0; i < n; i++) {
		words[i] = cases[i].word;
		buf[4 * i + 0] = (uint8_t)(cases[i].word);
		buf[4 * i + 1] = (uint8_t)(cases[i].word >> 8);
		buf[4 * i + 2] = (uint8_t)(cases[i].word >> 16);
		buf[4 * i + 3] = (uint8_t)(cases[i].word >> 24);
	}
	if (group_words_num < 8) {
		group_words[group_words_num] = words;
		group_words_len[group_words_num] = n;
		group_words_num++;
	}

	cnt = cs_disasm(handle, buf, n * 4, 0x1000, 0, &insns);
	check_field(group, cnt > 0, 0, 0, "count_nonzero", 1, (long long)cnt);
	check_field(group, cnt == n, 0, 0, "count", (long long)n,
		    (long long)cnt);
	m = cnt < n ? cnt : n;
	for (i = 0; i < m; i++)
		check_case(group, &cases[i], &insns[i], (unsigned)i);
	if (cnt)
		cs_free(insns, cnt);
}

/* ------------------------------------------------------------------ */
/* group: unsigned scaled offset                                       */
/* ------------------------------------------------------------------ */

static void group_unsigned_offset(void)
{
	tc_t cases[32];
	size_t n = 0;
	static const unsigned imm12s[] = { 0, 1, 4095 };
	int size, load;
	unsigned k;

	for (size = 0; size < 4; size++)
		for (load = 0; load < 2; load++)
			for (k = 0; k < 3; k++) {
				unsigned imm12 = imm12s[k];
				unsigned rt = 3, rn = 5;
				tc_t *t = &cases[n++];

				memset(t, 0, sizeof(*t));
				t->word = enc_unsigned(size, load, imm12, rn, rt);
				t->nops = 2;
				t->ops[0].type = ARM64_OP_REG;
				t->ops[0].reg = reg_for(size, rt);
				t->ops[0].acc = load ? CS_AC_WRITE : CS_AC_READ;
				t->ops[1].type = ARM64_OP_MEM;
				t->ops[1].base = xreg(rn);
				t->ops[1].index = ARM64_REG_INVALID;
				/* the offset is scaled by the access size */
				t->ops[1].disp = (int32_t)(imm12 << size);
				t->must_read[t->nread++] = xreg(rn);
				if (load) {
					t->must_write[t->nwrite++] = reg_for(size, rt);
					t->not_read[t->nnotread++] = reg_for(size, rt);
				} else {
					t->must_read[t->nread++] = reg_for(size, rt);
				}
				t->not_write[t->nnotwrite++] = xreg(rn);
				t->wb_base = ARM64_REG_INVALID;
			}
	run_cases("unsigned_offset", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: signed unscaled and pre-index                                */
/* ------------------------------------------------------------------ */

static void fill_imm9_case(tc_t *t, int size, int load, int mode, int imm,
			   unsigned rn, unsigned rt)
{
	memset(t, 0, sizeof(*t));
	t->word = enc_imm9(size, load, mode, imm, rn, rt);
	t->nops = 2;
	t->writeback = mode == 3;
	t->post_index = 0;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = reg_for(size, rt);
	t->ops[0].acc = load ? CS_AC_WRITE : CS_AC_READ;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = rn == 31 ? ARM64_REG_SP : xreg(rn);
	t->ops[1].index = ARM64_REG_INVALID;
	/* pre-index keeps the signed offset inside the MEM operand */
	t->ops[1].disp = sext((uint32_t)imm & 0x1ffu, 9);
	t->must_read[t->nread++] = t->ops[1].base;
	if (load) {
		t->must_write[t->nwrite++] = reg_for(size, rt);
		t->not_read[t->nnotread++] = reg_for(size, rt);
	} else {
		t->must_read[t->nread++] = reg_for(size, rt);
	}
	if (mode == 3)
		t->wb_base = t->ops[1].base;
	else {
		t->wb_base = ARM64_REG_INVALID;
		t->not_write[t->nnotwrite++] = t->ops[1].base;
	}
}

static void group_signed_pre(void)
{
	tc_t cases[40];
	size_t n = 0;
	static const int unscaled_imms[] = { -256, -8, 0, 255 };
	static const int pre_imms[] = { -256, -8, 16, 255 };
	static const int sizes[] = { 2, 3 };
	unsigned k;
	size_t s;
	int load;

	for (s = 0; s < 2; s++)
		for (load = 0; load < 2; load++) {
			for (k = 0; k < 4; k++)
				fill_imm9_case(&cases[n++], sizes[s], load, 0,
					       unscaled_imms[k], 6, 4);
			for (k = 0; k < 4; k++)
				fill_imm9_case(&cases[n++], sizes[s], load, 3,
					       pre_imms[k], 6, 4);
		}

	/* hand-written benchmark: ldr x0, [x1, #-8]! */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = 0xf85f8c20;
		t->nops = 2;
		t->writeback = 1;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_X0;
		t->ops[0].acc = CS_AC_WRITE;
		t->ops[1].type = ARM64_OP_MEM;
		t->ops[1].base = ARM64_REG_X1;
		t->ops[1].index = ARM64_REG_INVALID;
		t->ops[1].disp = -8;
		t->must_read[t->nread++] = ARM64_REG_X1;
		t->must_write[t->nwrite++] = ARM64_REG_X0;
		t->wb_base = ARM64_REG_X1;
	}
	run_cases("signed_pre", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: post-index                                                   */
/* ------------------------------------------------------------------ */

static void group_post_index(void)
{
	tc_t cases[40];
	size_t n = 0;
	static const int imms[] = { -256, -16, 8, 255 };
	static const int sizes[] = { 2, 3 };
	unsigned k;
	size_t s;
	int load;

	for (s = 0; s < 2; s++)
		for (load = 0; load < 2; load++)
			for (k = 0; k < 4; k++) {
				int imm = imms[k];
				unsigned rn = 3, rt = 2;
				tc_t *t = &cases[n++];

				memset(t, 0, sizeof(*t));
				t->word = enc_imm9(sizes[s], load, 1, imm, rn, rt);
				t->nops = 3;
				t->writeback = 1;
				t->post_index = 1;
				t->ops[0].type = ARM64_OP_REG;
				t->ops[0].reg = reg_for(sizes[s], rt);
				t->ops[0].acc = load ? CS_AC_WRITE : CS_AC_READ;
				t->ops[1].type = ARM64_OP_MEM;
				t->ops[1].base = xreg(rn);
				t->ops[1].index = ARM64_REG_INVALID;
				/* the memory operand itself carries no offset */
				t->ops[1].disp = 0;
				/* the update immediate is a separate operand */
				t->ops[2].type = ARM64_OP_IMM;
				t->ops[2].imm = sext((uint32_t)imm & 0x1ffu, 9);
				t->must_read[t->nread++] = xreg(rn);
				if (load) {
					t->must_write[t->nwrite++] = reg_for(sizes[s], rt);
					t->not_read[t->nnotread++] = reg_for(sizes[s], rt);
				} else {
					t->must_read[t->nread++] = reg_for(sizes[s], rt);
				}
				t->wb_base = xreg(rn);
			}

	/* hand-written benchmark: ldr x0, [x1], #8 */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = 0xf8408420;
		t->nops = 3;
		t->writeback = 1;
		t->post_index = 1;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_X0;
		t->ops[0].acc = CS_AC_WRITE;
		t->ops[1].type = ARM64_OP_MEM;
		t->ops[1].base = ARM64_REG_X1;
		t->ops[1].index = ARM64_REG_INVALID;
		t->ops[1].disp = 0;
		t->ops[2].type = ARM64_OP_IMM;
		t->ops[2].imm = 8;
		t->must_read[t->nread++] = ARM64_REG_X1;
		t->must_write[t->nwrite++] = ARM64_REG_X0;
		t->wb_base = ARM64_REG_X1;
	}
	run_cases("post_index", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: register offset with extend / shift                          */
/* ------------------------------------------------------------------ */

static void group_register_offset(void)
{
	tc_t cases[24];
	size_t n = 0;
	static const struct {
		unsigned option;
		arm64_extender ext;
		int is32;
	} extends[] = {
		{ 2, ARM64_EXT_UXTW, 1 },
		{ 3, ARM64_EXT_INVALID, 0 }, /* UXTX: the default, no ext */
		{ 6, ARM64_EXT_SXTW, 1 },
		{ 7, ARM64_EXT_SXTX, 0 },
	};
	size_t e;
	unsigned s;

	for (e = 0; e < 4; e++)
		for (s = 0; s < 2; s++) {
			unsigned rm = 2, rn = 1, rt = 0;
			tc_t *t = &cases[n++];

			memset(t, 0, sizeof(*t));
			t->word = enc_regoff(3, 1, rm, extends[e].option, s, rn, rt);
			t->nops = 2;
			t->ops[0].type = ARM64_OP_REG;
			t->ops[0].reg = ARM64_REG_X0;
			t->ops[0].acc = CS_AC_WRITE;
			t->ops[1].type = ARM64_OP_MEM;
			t->ops[1].base = xreg(rn);
			t->ops[1].index = extends[e].is32 ? wreg(rm) : xreg(rm);
			t->ops[1].disp = 0;
			t->ops[1].sft = s ? ARM64_SFT_LSL : ARM64_SFT_INVALID;
			t->ops[1].sval = s ? 3 : 0;
			t->ops[1].ext = extends[e].ext;
			t->must_read[t->nread++] = xreg(rn);
			t->must_read[t->nread++] = t->ops[1].index;
			t->must_write[t->nwrite++] = ARM64_REG_X0;
			t->not_read[t->nnotread++] = ARM64_REG_X0;
			t->wb_base = ARM64_REG_INVALID;
			t->not_write[t->nnotwrite++] = xreg(rn);
		}

	/* a store through a 32-bit extended index, scaled by 4 */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = enc_regoff(2, 0, 2, 2, 1, 1, 0); /* str w0, [x1, w2, uxtw #2] */
		t->nops = 2;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_W0;
		t->ops[0].acc = CS_AC_READ;
		t->ops[1].type = ARM64_OP_MEM;
		t->ops[1].base = ARM64_REG_X1;
		t->ops[1].index = ARM64_REG_W2;
		t->ops[1].disp = 0;
		t->ops[1].sft = ARM64_SFT_LSL;
		t->ops[1].sval = 2;
		t->ops[1].ext = ARM64_EXT_UXTW;
		t->must_read[t->nread++] = ARM64_REG_X1;
		t->must_read[t->nread++] = ARM64_REG_W2;
		t->must_read[t->nread++] = ARM64_REG_W0;
		t->wb_base = ARM64_REG_INVALID;
		t->not_write[t->nnotwrite++] = ARM64_REG_X1;
	}

	/* hand-written benchmark: ldr x0, [x1, w2, sxtw #3] */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = 0xf862d820;
		t->nops = 2;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_X0;
		t->ops[0].acc = CS_AC_WRITE;
		t->ops[1].type = ARM64_OP_MEM;
		t->ops[1].base = ARM64_REG_X1;
		t->ops[1].index = ARM64_REG_W2;
		t->ops[1].disp = 0;
		t->ops[1].sft = ARM64_SFT_LSL;
		t->ops[1].sval = 3;
		t->ops[1].ext = ARM64_EXT_SXTW;
		t->must_read[t->nread++] = ARM64_REG_X1;
		t->must_read[t->nread++] = ARM64_REG_W2;
		t->must_write[t->nwrite++] = ARM64_REG_X0;
		t->wb_base = ARM64_REG_INVALID;
		t->not_write[t->nnotwrite++] = ARM64_REG_X1;
	}
	run_cases("register_offset", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: load/store pair, signed scaled offset                        */
/* ------------------------------------------------------------------ */

static void group_pair(void)
{
	tc_t cases[40];
	size_t n = 0;
	static const int imm7s[] = { -64, -2, 0, 63 };
	int is64, load;
	unsigned k;

	for (is64 = 0; is64 < 2; is64++)
		for (load = 0; load < 2; load++)
			for (k = 0; k < 4; k++) {
				int imm7 = imm7s[k];
				int scale = is64 ? 3 : 2;
				unsigned rt = 0, rt2 = 1, rn = 2;
				tc_t *t = &cases[n++];

				memset(t, 0, sizeof(*t));
				t->word = enc_pair(is64, load, 0, imm7, rt2, rn, rt);
				t->nops = 3;
				t->ops[0].type = ARM64_OP_REG;
				t->ops[0].reg = reg_for(is64 ? 3 : 2, rt);
				t->ops[0].acc = load ? CS_AC_WRITE : CS_AC_READ;
				t->ops[1].type = ARM64_OP_REG;
				t->ops[1].reg = reg_for(is64 ? 3 : 2, rt2);
				t->ops[1].acc = load ? CS_AC_WRITE : CS_AC_READ;
				t->ops[2].type = ARM64_OP_MEM;
				t->ops[2].base = xreg(rn);
				t->ops[2].index = ARM64_REG_INVALID;
				/* imm7 scaled by the element size */
				t->ops[2].disp = sext((uint32_t)imm7 & 0x7fu, 7) << scale;
				t->must_read[t->nread++] = xreg(rn);
				if (load) {
					t->must_write[t->nwrite++] = t->ops[0].reg;
					t->must_write[t->nwrite++] = t->ops[1].reg;
				} else {
					t->must_read[t->nread++] = t->ops[0].reg;
					t->must_read[t->nread++] = t->ops[1].reg;
				}
				t->wb_base = ARM64_REG_INVALID;
				t->not_write[t->nnotwrite++] = xreg(rn);
			}

	/* pre-index pair: stp x0, x1, [sp, #-16]! */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = enc_pair(1, 0, 2, -2, 1, 31, 0);
		t->nops = 3;
		t->writeback = 1;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_X0;
		t->ops[0].acc = CS_AC_READ;
		t->ops[1].type = ARM64_OP_REG;
		t->ops[1].reg = ARM64_REG_X1;
		t->ops[1].acc = CS_AC_READ;
		t->ops[2].type = ARM64_OP_MEM;
		t->ops[2].base = ARM64_REG_SP;
		t->ops[2].index = ARM64_REG_INVALID;
		t->ops[2].disp = -16;
		t->must_read[t->nread++] = ARM64_REG_SP;
		t->must_read[t->nread++] = ARM64_REG_X0;
		t->must_read[t->nread++] = ARM64_REG_X1;
		t->wb_base = ARM64_REG_SP;
	}

	/* post-index pair: ldp x0, x1, [sp], #16 */
	{
		tc_t *t = &cases[n++];

		memset(t, 0, sizeof(*t));
		t->word = enc_pair(1, 1, 1, 2, 1, 31, 0);
		t->nops = 4;
		t->writeback = 1;
		t->post_index = 1;
		t->ops[0].type = ARM64_OP_REG;
		t->ops[0].reg = ARM64_REG_X0;
		t->ops[0].acc = CS_AC_WRITE;
		t->ops[1].type = ARM64_OP_REG;
		t->ops[1].reg = ARM64_REG_X1;
		t->ops[1].acc = CS_AC_WRITE;
		t->ops[2].type = ARM64_OP_MEM;
		t->ops[2].base = ARM64_REG_SP;
		t->ops[2].index = ARM64_REG_INVALID;
		t->ops[2].disp = 0;
		t->ops[3].type = ARM64_OP_IMM;
		t->ops[3].imm = 16;
		t->must_read[t->nread++] = ARM64_REG_SP;
		t->must_write[t->nwrite++] = ARM64_REG_X0;
		t->must_write[t->nwrite++] = ARM64_REG_X1;
		t->wb_base = ARM64_REG_SP;
	}
	run_cases("pair", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: register 31 as the base means SP                             */
/* ------------------------------------------------------------------ */

static void group_sp_base(void)
{
	tc_t cases[8];
	size_t n = 0;
	tc_t *t;

	/* ldr x0, [sp, #8] */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_unsigned(3, 1, 1, 31, 0);
	t->nops = 2;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_X0;
	t->ops[0].acc = CS_AC_WRITE;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_SP;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = 8;
	t->must_read[t->nread++] = ARM64_REG_SP;
	t->must_write[t->nwrite++] = ARM64_REG_X0;
	t->wb_base = ARM64_REG_INVALID;
	t->not_write[t->nnotwrite++] = ARM64_REG_SP;

	/* str w5, [sp] (zero offset) */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_unsigned(2, 0, 0, 31, 5);
	t->nops = 2;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_W5;
	t->ops[0].acc = CS_AC_READ;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_SP;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = 0;
	t->must_read[t->nread++] = ARM64_REG_SP;
	t->must_read[t->nread++] = ARM64_REG_W5;
	t->wb_base = ARM64_REG_INVALID;
	t->not_write[t->nnotwrite++] = ARM64_REG_SP;

	/* ldur x0, [sp, #-256] (most negative 9-bit offset) */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_imm9(3, 1, 0, -256, 31, 0);
	t->nops = 2;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_X0;
	t->ops[0].acc = CS_AC_WRITE;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_SP;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = -256;
	t->must_read[t->nread++] = ARM64_REG_SP;
	t->must_write[t->nwrite++] = ARM64_REG_X0;
	t->wb_base = ARM64_REG_INVALID;
	t->not_write[t->nnotwrite++] = ARM64_REG_SP;

	/* ldur x0, [sp, #255] (most positive 9-bit offset) */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_imm9(3, 1, 0, 255, 31, 0);
	t->nops = 2;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_X0;
	t->ops[0].acc = CS_AC_WRITE;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_SP;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = 255;
	t->must_read[t->nread++] = ARM64_REG_SP;
	t->must_write[t->nwrite++] = ARM64_REG_X0;
	t->wb_base = ARM64_REG_INVALID;
	t->not_write[t->nnotwrite++] = ARM64_REG_SP;

	/* ldr x0, [sp, #-8]! (pre-index updates SP) */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_imm9(3, 1, 3, -8, 31, 0);
	t->nops = 2;
	t->writeback = 1;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_X0;
	t->ops[0].acc = CS_AC_WRITE;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_SP;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = -8;
	t->must_read[t->nread++] = ARM64_REG_SP;
	t->must_write[t->nwrite++] = ARM64_REG_X0;
	t->wb_base = ARM64_REG_SP;

	/* ldr xzr, [x1, #-8]! (register 31 in a data position is XZR) */
	t = &cases[n++];
	memset(t, 0, sizeof(*t));
	t->word = enc_imm9(3, 1, 3, -8, 1, 31);
	t->nops = 2;
	t->writeback = 1;
	t->ops[0].type = ARM64_OP_REG;
	t->ops[0].reg = ARM64_REG_XZR;
	t->ops[0].acc = CS_AC_WRITE;
	t->ops[1].type = ARM64_OP_MEM;
	t->ops[1].base = ARM64_REG_X1;
	t->ops[1].index = ARM64_REG_INVALID;
	t->ops[1].disp = -8;
	t->must_read[t->nread++] = ARM64_REG_X1;
	t->must_write[t->nwrite++] = ARM64_REG_XZR;
	t->wb_base = ARM64_REG_X1;

	run_cases("sp_base", cases, n);
}

/* ------------------------------------------------------------------ */
/* group: cs_disasm vs cs_disasm_iter over one interleaved stream      */
/* ------------------------------------------------------------------ */

static void compare_reg_sets(unsigned idx, uint32_t word, const cs_insn *a,
			     const cs_insn *b)
{
	cs_regs rd_a, wr_a, rd_b, wr_b;
	uint8_t nr_a = 0, nw_a = 0, nr_b = 0, nw_b = 0;
	unsigned i;

	if (cs_regs_access(handle, a, rd_a, &nr_a, wr_a, &nw_a) != CS_ERR_OK ||
	    cs_regs_access(handle, b, rd_b, &nr_b, wr_b, &nw_b) != CS_ERR_OK) {
		tag_hit("api_reuse");
		printf("FAIL api_reuse word=0x%08x idx=%u field=regs_access error\n",
		       word, idx);
		return;
	}
	check_field("api_reuse", nr_a == nr_b, word, idx, "regs_read_count",
		    nr_a, nr_b);
	check_field("api_reuse", nw_a == nw_b, word, idx, "regs_write_count",
		    nw_a, nw_b);
	for (i = 0; i < nr_a && i < nr_b; i++)
		check_field("api_reuse", rd_a[i] == rd_b[i], word, idx,
			    "regs_read", rd_a[i], rd_b[i]);
	for (i = 0; i < nw_a && i < nw_b; i++)
		check_field("api_reuse", wr_a[i] == wr_b[i], word, idx,
			    "regs_write", wr_a[i], wr_b[i]);
}

static void compare_insns(unsigned idx, const cs_insn *a, const cs_insn *b)
{
	uint32_t word = (uint32_t)a->bytes[0] | ((uint32_t)a->bytes[1] << 8) |
			((uint32_t)a->bytes[2] << 16) | ((uint32_t)a->bytes[3] << 24);
	const cs_arm64 *aa = &a->detail->arm64;
	const cs_arm64 *bb = &b->detail->arm64;
	unsigned j, nop;

	check_field("api_reuse", a->address == b->address, word, idx, "address",
		    (long long)a->address, (long long)b->address);
	check_field("api_reuse", a->size == b->size, word, idx, "size",
		    a->size, b->size);
	check_field("api_reuse", memcmp(a->bytes, b->bytes, 4) == 0, word, idx,
		    "bytes", 0, 1);
	check_field("api_reuse", a->id == b->id, word, idx, "id", a->id, b->id);
	check_field("api_reuse", aa->op_count == bb->op_count, word, idx,
		    "op_count", aa->op_count, bb->op_count);
	check_field("api_reuse", (int)aa->writeback == (int)bb->writeback, word,
		    idx, "writeback", aa->writeback, bb->writeback);
	check_field("api_reuse", (int)aa->post_index == (int)bb->post_index,
		    word, idx, "post_index", aa->post_index, bb->post_index);
	nop = aa->op_count < bb->op_count ? aa->op_count : bb->op_count;
	for (j = 0; j < nop; j++) {
		const cs_arm64_op *x = &aa->operands[j];
		const cs_arm64_op *y = &bb->operands[j];
		char field[32];

		snprintf(field, sizeof(field), "op%u.type", j);
		check_field("api_reuse", x->type == y->type, word, idx, field,
			    x->type, y->type);
		snprintf(field, sizeof(field), "op%u.reg", j);
		check_field("api_reuse", x->reg == y->reg, word, idx, field,
			    x->reg, y->reg);
		snprintf(field, sizeof(field), "op%u.imm", j);
		check_field("api_reuse", x->imm == y->imm, word, idx, field,
			    (long long)x->imm, (long long)y->imm);
		snprintf(field, sizeof(field), "op%u.mem.base", j);
		check_field("api_reuse", x->mem.base == y->mem.base, word, idx,
			    field, x->mem.base, y->mem.base);
		snprintf(field, sizeof(field), "op%u.mem.index", j);
		check_field("api_reuse", x->mem.index == y->mem.index, word, idx,
			    field, x->mem.index, y->mem.index);
		snprintf(field, sizeof(field), "op%u.mem.disp", j);
		check_field("api_reuse", x->mem.disp == y->mem.disp, word, idx,
			    field, x->mem.disp, y->mem.disp);
		snprintf(field, sizeof(field), "op%u.shift.type", j);
		check_field("api_reuse", x->shift.type == y->shift.type, word,
			    idx, field, x->shift.type, y->shift.type);
		snprintf(field, sizeof(field), "op%u.shift.value", j);
		check_field("api_reuse", x->shift.value == y->shift.value, word,
			    idx, field, x->shift.value, y->shift.value);
		snprintf(field, sizeof(field), "op%u.ext", j);
		check_field("api_reuse", x->ext == y->ext, word, idx, field,
			    x->ext, y->ext);
		snprintf(field, sizeof(field), "op%u.access", j);
		check_field("api_reuse", x->access == y->access, word, idx,
			    field, x->access, y->access);
	}
	compare_reg_sets(idx, word, a, b);
}

static void group_api_reuse(void)
{
	size_t total = 0, pos = 0, n1, n2 = 0;
	unsigned g;
	uint8_t *buf;
	const uint8_t *code;
	size_t size;
	uint64_t address, base = 0x4000;
	cs_insn *all = NULL, *one;

	for (g = 0; g < group_words_num; g++)
		total += group_words_len[g];

	/* interleave the groups so update and non-update forms mix, and
	 * leave a trailing two-byte stub that must stay unconsumed */
	buf = (uint8_t *)malloc(4 * total + 2);
	if (!buf) {
		tag_hit("api_reuse");
		printf("FAIL api_reuse out of memory\n");
		return;
	}
	{
		size_t cursor[8] = { 0, 0, 0, 0, 0, 0, 0, 0 };

		while (pos < total) {
			int emitted = 0;

			for (g = 0; g < group_words_num; g++) {
				if (cursor[g] >= group_words_len[g])
					continue;
				uint32_t w = group_words[g][cursor[g]++];

				buf[4 * pos + 0] = (uint8_t)w;
				buf[4 * pos + 1] = (uint8_t)(w >> 8);
				buf[4 * pos + 2] = (uint8_t)(w >> 16);
				buf[4 * pos + 3] = (uint8_t)(w >> 24);
				pos++;
				emitted = 1;
			}
			if (!emitted)
				break;
		}
	}
	check_field("api_reuse", pos == total, 0, 0, "weave_count",
		    (long long)total, (long long)pos);
	buf[4 * total + 0] = 0x5a;
	buf[4 * total + 1] = 0xa5;

	n1 = cs_disasm(handle, buf, 4 * total + 2, base, 0, &all);
	check_field("api_reuse", n1 > 0, 0, 0, "disasm_nonzero", 1,
		    (long long)n1);
	check_field("api_reuse", n1 == total, 0, 0, "disasm_count",
		    (long long)total, (long long)n1);

	/* iterate over the same stream, reusing a single cs_malloc() result */
	one = cs_malloc(handle);
	if (!one) {
		tag_hit("api_reuse");
		printf("FAIL api_reuse cs_malloc returned NULL\n");
		free(buf);
		if (n1)
			cs_free(all, n1);
		return;
	}
	code = buf;
	size = 4 * total + 2;
	address = base;
	while (cs_disasm_iter(handle, &code, &size, &address, one)) {
		if (n2 < n1)
			compare_insns((unsigned)n2, &all[n2], one);
		n2++;
	}
	/* the valid prefix must not be lost and the stub must remain */
	check_field("api_reuse", n2 == total, 0, 0, "iter_count",
		    (long long)total, (long long)n2);
	check_field("api_reuse", size == 2, 0, 0, "iter_size_left", 2,
		    (long long)size);
	check_field("api_reuse", code == buf + 4 * total, 0, 0, "iter_code",
		    (long long)(buf + 4 * total), (long long)code);
	check_field("api_reuse", address == base + 4 * total, 0, 0,
		    "iter_address", (long long)(base + 4 * total),
		    (long long)address);

	if (one)
		cs_free(one, 1);
	if (n1)
		cs_free(all, n1);
	free(buf);
}

/* ------------------------------------------------------------------ */

int main(void)
{
	static const char *const groups[] = {
		"unsigned_offset", "signed_pre", "post_index",
		"register_offset", "pair", "sp_base", "api_reuse",
	};
	unsigned i;

	if (cs_open(CS_ARCH_ARM64, CS_MODE_ARM, &handle) != CS_ERR_OK) {
		fprintf(stderr, "cs_open failed\n");
		return 2;
	}
	if (cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON) != CS_ERR_OK) {
		fprintf(stderr, "cs_option failed\n");
		return 2;
	}

	group_unsigned_offset();
	group_signed_pre();
	group_post_index();
	group_register_offset();
	group_pair();
	group_sp_base();
	group_api_reuse();

	for (i = 0; i < sizeof(groups) / sizeof(groups[0]); i++)
		if (!tag_failed(groups[i]))
			printf("PASS %s\n", groups[i]);

	cs_close(&handle);
	return total_failures ? 1 : 0;
}
